  // --- chrome state ---------------------------------------------------------
  private viewOnly = false;
  private latchCtrl = false;
  private latchAlt = false;
  private inputMode: InputMode = 'pointer';
  /** The remembered choice behind inputMode ('auto' follows the device). */
