  private adaptiveFpsTarget = 30;
  private adaptiveFps = false;
  private adaptiveStableSamples = 0;
  private lastDroppedFrames = 0;
  private codecSupport: Array<'auto'|'vp9'|'h264'|'h265'|'vp8'|'av1'> = ['auto'];
  private preferredCodec = 'auto';
